import json, urllib.request, urllib.error

API_KEY = "[REDACTED_GALAXY_API_KEY]"
BASE = "https://usegalaxy.org/api"
SEED_ID = "bbd44e69cb8906b581fc4af08df12309"
NEW_HIST_ID = "bbd44e69cb8906b508f9d965cf072bbe"

def req(url, method="GET", data=None):
    headers = {"x-api-key": API_KEY, "Accept": "application/json"}
    if data:
        headers["Content-Type"] = "application/json"
        data = json.dumps(data).encode()
    r = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(r) as resp:
            return json.loads(resp.read())
    except urllib.error.HTTPError as e:
        print(f"Error {e.code}: {e.reason}")
        body = e.read().decode()
        print(body[:500])
        return None

# Get datasets from seed
contents = req(f"{BASE}/histories/{SEED_ID}/contents")
if not contents:
    print("Failed to get seed contents")
    exit()

print(f"Copying {len(contents)} datasets...")

# Copy each dataset to the new history
for ds in contents:
    ds_id = ds['id']
    ds_name = ds['name']
    print(f"  Copying: {ds_name} ({ds_id})")

    result = req(
        f"{BASE}/histories/{NEW_HIST_ID}/contents/datasets",
        method="POST",
        data={
            "source": "hda",
            "content": ds_id
        }
    )
    if result:
        print(f"    -> {result.get('id')} state={result.get('state')}")
    else:
        print(f"    FAILED")

# Verify
print("\n=== Verifying new history contents ===")
new_contents = req(f"{BASE}/histories/{NEW_HIST_ID}/contents")
if new_contents:
    for ds in new_contents:
        print(f"  {ds['name']} ({ds['id']}) - {ds.get('state')}")
PYEOF

